/* subject.lpc
 *
 * Demonstration of the interactive / process_input() hook.
 *
 * If a player object defines process_input(), the driver hands it a copy of
 * every line the player types before the command parser sees it.  Returning
 * a non-zero string replaces the line the driver goes on to parse; returning
 * 0 lets the original input through untouched.
 */

private string *history;
private int history_limit = 20;

public int cmd_history()
{
    if (!history || !sizeof(history))
        write("You have no command history.\n");
    else {
        write("Your last commands:\n");
        for (int i = sizeof(history) - 1; i >= 0; i--)
            write(sprintf("  %d. %s\n", sizeof(history) - i, history[i]));
    }
    return 1;
}

public string process_input(string line)
{
    if (!line) return 0;

    /* keep a private, un-mangled copy of exactly what the player typed */
    if (line != "history") {
        if (!history) history = ({ });
        history += ({ line });
        if (sizeof(history) > history_limit)
            history = history[1..$];
    }

    /* strip control characters and trailing whitespace (wizcuff protection) */
    line = regexp_replace(line, "[\\x00-\\x1f\\x7f]", " ");
    line = trim(line);
    if (line == "") return 0;

    /* shorthand commands, resolved before the parser ever runs */
    switch (line) {
    case "l":       return "look";
    case "i":       return "inventory";
    case "q":       return "quit";
    case "h":       line = "history"; break;
    default:        break;
    }

    /* "history" is handled above; everything else is the cleaned-up line */
    if (line == "history") {
        cmd_history();
        return "";              /* consumed, nothing is re-parsed */
    }

    return line;
}
