// process_input: expand shorthand command aliases before the command runs.
// Only the leading verb is rewritten, so arguments (and any quoted text)
// are passed through untouched.

private mapping aliases = ([
    "l"   : "look",
    "ls"  : "look",
    "i"   : "inventory",
    "inv" : "inventory",
    "st"  : "status",
    "we"  : "wear",
    "rw"  : "remove",
    "dr"  : "drop",
    "gi"  : "give",
    "ta"  : "take",
    "o"   : "open",
    "cl"  : "close",
    "pu"  : "pull",
    "pi"  : "pick",
    "ch"  : "chat",
    "t"   : "talk",
    "e"   : "eat",
    "d"   : "drink",
    "q"   : "quit",
]);

public string process_input(string line) {
    string verb, rest, expanded;

    line = trim(line);
    if (line == "") return line;

    verb = word_at(line, 1);
    if (!isstring(verb) || verb == "") return line;

    expanded = aliases[verb];
    if (!isstring(expanded)) return line;

    rest = line[ strlen(verb) .. -1 ];
    return expanded + rest;
}
